<?php
declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Assessment;use Acorn\SafetyHealthcheck\Content\{ContentVersionRepository,QuestionRepository,RecommendationRepository};use Acorn\SafetyHealthcheck\Database\Schema;use Acorn\SafetyHealthcheck\Domain\{ApplicabilityContext,AssessmentState,AnswerValue,RulesEngine,ResultsEngine,OpportunityTagger};use RuntimeException;
final class AssessmentService{private AssessmentRepository $repo;private AnswerRepository $answers;public function __construct(){ $this->repo=new AssessmentRepository;$this->answers=new AnswerRepository;}public function start():array{global $wpdb;$v=(new ContentVersionRepository)->getPublished();$t=AssessmentRepository::token();$now=current_time('mysql');$wpdb->insert(Schema::table('assessments'),['assessment_token_hash'=>hash('sha256',$t),'status'=>'in_progress','content_version_id'=>$v['id'],'profile_json'=>'{}','service_tags_json'=>'[]','started_at'=>$now,'last_activity_at'=>$now]);return['token'=>$t,'state'=>$this->resume($t)];}public function resume(string $t):AssessmentState{$a=$this->require($t);$qs=[];$p=json_decode($a['profile_json'],true);if($p)$qs=(new RulesEngine)->applicableQuestions(ApplicabilityContext::fromProfile($p),(new QuestionRepository)->forVersion((int)$a['content_version_id']));return new AssessmentState($a,$qs,$this->answers->all((int)$a['id']));}public function updateProfile(string $t,array $p):AssessmentState{global $wpdb;$a=$this->requireMutable($t);$c=ApplicabilityContext::fromProfile($p);$qs=(new RulesEngine)->applicableQuestions($c,(new QuestionRepository)->forVersion((int)$a['content_version_id']));$wpdb->update(Schema::table('assessments'),['profile_json'=>wp_json_encode($p),'jurisdiction'=>$p['jurisdiction'],'employee_band'=>$p['employee_band'],'sector'=>$p['sector'],'last_activity_at'=>current_time('mysql')],['id'=>$a['id']]);$this->answers->deleteExcluded((int)$a['id'],array_column($qs,'question_key'));return$this->resume($t);}public function saveAnswer(string $t,string $key,string $answer):AssessmentState{global $wpdb;$a=$this->requireMutable($t);$state=$this->resume($t);$q=null;foreach($state->questions as $candidate)if($candidate['question_key']===$key)$q=$candidate;if(!$q)throw new RuntimeException('Question is not applicable.');$answer=AnswerValue::assert($answer);$rec=$answer==='yes'?null:(new RecommendationRepository)->resolve((int)$a['content_version_id'],$key,$answer,$a['jurisdiction']);$status=$answer==='yes'?'addressed':$rec['finding_status'];$wpdb->replace(Schema::table('answers'),['assessment_id'=>$a['id'],'question_key'=>$key,'question_row_id'=>$q['id'],'answer_value'=>$answer,'finding_status'=>$status,'recommendation_row_id'=>$rec['id']??null,'answered_at'=>current_time('mysql')]);return$this->resume($t);}public function assess(string $t):array{global $wpdb;$a=$this->requireMutable($t);$s=$this->resume($t);$map=[];foreach($s->answers as $x)$map[$x['question_key']]=$x['answer_value'];if(count($map)!==count($s->questions))throw new RuntimeException('Answer all applicable questions.');$r=(new ResultsEngine)->evaluate($s->questions,$map,$a['jurisdiction'],(int)$a['content_version_id']);$tags=(new OpportunityTagger)->tags($r['findings']);$wpdb->update(Schema::table('assessments'),['status'=>'assessed','priority_count'=>$r['priority_count'],'review_count'=>$r['review_count'],'addressed_count'=>$r['addressed_count'],'overall_status'=>$r['overall_status'],'service_tags_json'=>wp_json_encode($tags),'assessed_at'=>current_time('mysql')],['id'=>$a['id']]);return$r;}private function require(string $t):array{$a=$this->repo->findByToken($t);if(!$a)throw new RuntimeException('Assessment not found.');return$a;}private function requireMutable(string $t):array{$a=$this->require($t);if($a['status']==='completed')throw new RuntimeException('Assessment is locked.');return$a;}}
